// Parses the "New subscription confirmation" email from receipt@trainingpeaks.com
const results = [];

for (const item of $input.all()) {
  // Collapse all whitespace/line-wraps so multi-line fields become single-line before matching
  const flat = (item.json.textPlain || '').replace(/\s+/g, ' ').trim();

  const nameEmail = flat.match(/Customer Name:\s*([^(]+?)\s*\(([^)]+)\)/i);
  const subMatch = flat.match(/Subscription:\s*([\s\S]+?)\s-\s\$/);
  const invoiceMatch = flat.match(/Invoice Number:\s*(\S+)/i);
  const amountMatch = flat.match(/Amount Charged:\s*\$([\d.,]+)/i);

  const fullName = nameEmail ? nameEmail[1].trim() : '';
  // Latin naming: first non-initial token is the given name, the rest is the
  // surname. "Paula Maria Gonzalez" -> "Paula" / "Maria Gonzalez". The old rule
  // popped only the LAST token, which is right on a two-token name and wrong on
  // the two-surname norm -- it put the whole string into firstname. Same fix as
  // the CoachMatch lead parser, September 4, 2026.
  const titleCase = (s) => s.replace(
    /[\p{L}][\p{L}'\u2019-]*/gu,
    (t) => t.charAt(0).toLocaleUpperCase('es') + t.slice(1).toLocaleLowerCase('es')
  );
  const isInitial = (t) => /^[\p{L}]\.?$/u.test(t);
  const isShouted = (s) => s === s.toLocaleUpperCase('es') && /\p{Lu}/u.test(s);
  const isAllLower = (s) => s === s.toLocaleLowerCase('es') && /\p{Ll}/u.test(s);

  const cleanName = (isShouted(fullName) || isAllLower(fullName)) ? titleCase(fullName) : fullName;
  const nameParts = cleanName.split(/\s+/).filter(Boolean);

  let firstIdx = nameParts.findIndex((t) => !isInitial(t));
  if (firstIdx === -1) firstIdx = 0;
  const firstname = nameParts[firstIdx] || '';
  const lastname = nameParts.slice(firstIdx + 1).join(' ');

  results.push({
    json: {
      firstname,
      lastname,
      email: nameEmail ? nameEmail[2].trim() : '',
      subscription_name: subMatch ? subMatch[1].trim() : '',
      invoice_number: invoiceMatch ? invoiceMatch[1] : '',
      amount_charged: amountMatch ? amountMatch[1] : '',
      source_subject: item.json.subject,
      source_date: item.json.date,
    }
  });
}

return results;

// Detects which All-Access product (ES/EN/PT) this is from the confirmed real
// product names in TP Payments (see triaperformance-pricing-and-positioning.md).
//
// UPDATED August 13, 2026 — the ES and EN products were renamed to align the
// checkout title with what the site calls the product ("All-Access"). The old
// matchers keyed on "suscripci" and "full access", BOTH of which vanished in the
// rename, so every new ES and EN subscription silently became UNKNOWN: no
// welcome email, no members token, no correct customerType. PT was untouched.
//
// Old strings are deliberately KEPT alongside the new ones — a renewal or a
// retry carrying the old title must still classify. Matching costs nothing;
// failing to match costs a paying subscriber their entire onboarding.
//
// Order matters: PT is checked first because "All-Access" now appears in both
// the ES and EN titles, so the discriminator is the language of the body text.

function detectLanguage(subscriptionName) {
  const s = (subscriptionName || '').toLowerCase();
  if (s.includes('acesso total')) return 'PORTUGUESE';
  if (s.includes('todos los planes') || (s.includes('suscripci') && s.includes('triaperformance'))) return 'SPANISH';
  if (s.includes('all training plans') || s.includes('full access')) return 'ENGLISH';
  return null;
}

const results = [];

for (const item of $input.all()) {
  const d = item.json;
  const preferredLanguage = detectLanguage(d.subscription_name);

  results.push({
    json: {
      firstname: d.firstname,
      lastname: d.lastname,
      email: d.email,
      subscription_name: d.subscription_name,
      invoice_number: d.invoice_number,
      amount_charged: d.amount_charged,
      preferredLanguage, // null if unrecognized -- check Telegram alert if so
      language_unrecognized: preferredLanguage === null,
    }
  });
}

return results;

// Generates a readable-ish random token to double as the member's "password".
// Avoids ambiguous characters (0/O, 1/l/I) since it's typed into a password field.
// Uses Math.random() rather than the crypto module -- n8n's sandboxed task runner
// disallows Node built-in modules by default, and this doesn't need
// cryptographic-grade randomness, just enough to not be guessable.
const alphabet = 'ABCDEFGHJKMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';

function genToken(length = 20) {
  let out = '';
  for (let i = 0; i < length; i++) {
    out += alphabet[Math.floor(Math.random() * alphabet.length)];
  }
  return out;
}

return $input.all().map(item => ({
  json: {
    ...item.json,
    member_token: genToken(),
  }
}));

