// Resend-password email, ES/EN/PT. Added Aug 10, 2026 (members-area i18n branch).
//
// Language comes from `preferred_language` on the subscriber_tokens row, NOT from
// the `lang` the forgot-password page posts. Same reasoning as the login routing
// in auth_service/app.py: the database knows who they are, the page only knows
// which screen they happened to open -- someone can land on the Spanish recovery
// page and still be a Portuguese subscriber. `Look Up Active Token` already
// SELECTs preferred_language, so no extra lookup is needed.
//
// Values are SPANISH/ENGLISH/PORTUGUESE (cached from Twenty); anything
// unrecognised falls back to Spanish, same rule as the welcome emails.
//
// pairedItem is set deliberately: Send Resend Email resolves the recipient with
// $('Webhook - Resend Password').item, which needs item lineage preserved across
// this node. Without it, inserting this node breaks that lookup.

const LOGIN_URL = {
  SPANISH:    'https://triaperformance.com/members/login',
  ENGLISH:    'https://triaperformance.com/members/en/login',
  PORTUGUESE: 'https://triaperformance.com/members/pt/login',
};

const T = {
  SPANISH: (tok) => ({
    subject: 'Tu contraseña del Área de Miembros - Triaperformance',
    text: `Hola,

Recibimos tu solicitud de recuperar tu contraseña del Área de Miembros.

Link: ${LOGIN_URL.SPANISH}
Contraseña: ${tok}

Si no fuiste tú, ignora este email — tu acceso no cambió.

Iván Koch - Triaperformance`,
  }),
  ENGLISH: (tok) => ({
    subject: 'Your Member Area password - Triaperformance',
    text: `Hi,

We received your request to recover your Member Area password.

Link: ${LOGIN_URL.ENGLISH}
Password: ${tok}

If this wasn't you, ignore this email — your access hasn't changed.

Iván Koch - Triaperformance`,
  }),
  PORTUGUESE: (tok) => ({
    subject: 'Sua senha da Área de Membros - Triaperformance',
    text: `Olá,

Recebemos seu pedido de recuperação da senha da Área de Membros.

Link: ${LOGIN_URL.PORTUGUESE}
Senha: ${tok}

Se não foi você, ignore este email — seu acesso não mudou.

Iván Koch - Triaperformance`,
  }),
};

return $input.all().map((item, i) => {
  const tok = item.json.token;
  if (!tok) {
    throw new Error('Build Resend Email: no token on the item -- Token Found? should have routed this to the generic-response branch.');
  }
  const raw = item.json.preferred_language;
  const lang = T[raw] ? raw : 'SPANISH';
  return { json: { ...T[lang](tok), token: tok, langUsed: lang, langWasKnown: Boolean(T[raw]) }, pairedItem: i };
});

// Classifies a "New subscription confirmation" into a product family.
// BOTH allowlists are explicit, and anything matching neither is UNKNOWN.
// UNKNOWN must never fall through to a default customerType -- that was the
// August 2026 bug: this branch had no UNKNOWN case, so an unrecognised product
// proceeded with customerType 'ALL_ACCESS' hardcoded as an implicit default.

const ALL_ACCESS_MATCHERS = [
  // Renamed Aug 13, 2026: both the ES and EN titles now carry "all-access".
  s => s.includes('all-access'),
  s => s.includes('acesso total'),
  // Pre-rename titles, kept so an in-flight or renewal email still classifies.
  s => s.includes('suscripci') && s.includes('triaperformance'),
  s => s.includes('full access'),
];

// Confirmed by Ivan, Aug 8 2026: exactly one active Private product,
// "Triaperformance 1-1 Coaching" ($149/mo + $50 startup, promocode NOSTARTUP).
// The retired "Coaching personalizado - Un deporte (...)" is deliberately NOT
// listed -- if it ever reappears it should alert, not be silently accepted.
const PRIVATE_COACHING_MATCHERS = [
  s => s.includes('1-1 coaching'),
];

return $input.all().map(item => {
  const j = item.json;
  const s = (j.subscription_name || '').toLowerCase();

  let productType = 'UNKNOWN';
  if (ALL_ACCESS_MATCHERS.some(fn => fn(s))) {
    productType = 'ALL_ACCESS';
  } else if (PRIVATE_COACHING_MATCHERS.some(fn => fn(s))) {
    productType = 'PRIVATE_COACHING';
  }

  return { json: { ...j, productType } };
});

